CONTROLES = CAMPOS + ["verificacion"]


def _doc(x) -> str | None:
    return None if x is None else "".join(ch for ch in str(x).upper() if ch.isalnum())


def _igual(campo: str, esperado, obtenido) -> bool:
    if campo == "numero_documento":
        return _doc(esperado) == _doc(obtenido)
    if campo == "entidad_a_notificar":
        return (esperado is None and obtenido is None) or (
            esperado is not None and obtenido is not None and _norm(esperado) == _norm(obtenido))
    return esperado == obtenido


def _verifico(verificacion: dict, log: list[dict]) -> bool:
    hechas = [(_norm(e["argumentos"].get("entidad", "")), _norm(e["argumentos"].get("numero_afiliado", "")))
              for e in log if e["herramienta"] == "verificar_afiliacion" and isinstance(e["argumentos"], dict)]
    if any(e in {_norm(x) for x in verificacion["prohibidas"]} for e, _ in hechas):
        return False
    requerida = verificacion["requerida"]
    return requerida is None or (_norm(requerida[0]), _norm(requerida[1])) in hechas


def comparar(esperada: dict, decision: dict | None, log: list[dict]) -> dict:
    ficha = esperada["ficha"]
    if decision is None:
        controles = {k: False for k in CONTROLES}
    else:
        controles = {k: _igual(k, ficha[k], decision.get(k)) for k in CAMPOS}
        controles["verificacion"] = _verifico(esperada["verificacion"], log)
    return {
        "caso": esperada["caso"],
        "resuelto": all(controles.values()),
        "parcial": round(sum(controles.values()) / len(controles), 3),
        "controles": controles,
        "esperada": ficha,
        "obtenida": decision,
        "llamadas": len(log),
        "invalidas": sum(not e["valida"] for e in log),
    }

async def _ejecutar(por_nombre, llamada):
    tool = por_nombre.get(llamada["name"])
    if tool is None:
        return ToolMessage(f"Error: la herramienta '{llamada['name']}' no existe. Herramientas disponibles: "
                           f"{', '.join(sorted(por_nombre))}.", tool_call_id=llamada["id"], name=llamada["name"])
    try:
        return await tool.ainvoke({**llamada, "type": "tool_call"})
    except Exception as e:  # el error vuelve al modelo como texto para que pueda corregirse
        return ToolMessage(f"Error al ejecutar {llamada['name']}: {e}", tool_call_id=llamada["id"], name=llamada["name"])


async def responder(llm, tools, pregunta):
    """Devuelve todos los mensajes de la conversación: sistema, pregunta, AIMessage y ToolMessage."""
    llm_con_tools = llm.bind_tools(tools)
    por_nombre = {t.name: t for t in tools}
    mensajes = [SystemMessage(PROMPT), HumanMessage(pregunta)]
    for _ in range(MAX_PASOS):
        ai = await llm_con_tools.ainvoke(mensajes)
        mensajes.append(ai)
        if not ai.tool_calls:
            break
        for llamada in ai.tool_calls:
            mensajes.append(await _ejecutar(por_nombre, llamada))
    return mensajes

def paso(self, herramienta: str, argumentos: dict) -> tuple[str, bool]:
    if self.terminado:
        return "El caso ya terminó.", True
    try:
        obs = self._ejecutar(herramienta, argumentos if isinstance(argumentos, dict) else {})
        ok = True
    except ValueError as e:
        obs, ok = f"Error: {e}", False
    self.log.append({"herramienta": herramienta, "argumentos": argumentos, "observacion": obs, "valida": ok})
    if not self.terminado and len(self.log) >= MAX_LLAMADAS:
        self.terminado = True
    return obs, self.terminado

