# Solo la atención del modelo de lenguaje. Gemma 4 es multimodal: sus torres de visión y audio también
# tienen q_proj/v_proj, pero son Gemma4ClippableLinear y PEFT no los soporta (falló en Kaggle). PEFT
# aplica un string con re.fullmatch sobre el nombre completo del módulo (peft/utils/other.py:1521).
LORA_OBJETIVO = r"(.*\.)?language_model\.layers\.\d+\.self_attn\.(q_proj|v_proj)"
LORA = {"r": 8, "lora_alpha": 16, "lora_dropout": 0.0,
        "target_modules": LORA_OBJETIVO, "task_type": "CAUSAL_LM"}
POLITICA = {"save_steps": 50, "bf16": True, "gradient_checkpointing": True,
            "gradient_checkpointing_kwargs": {"use_reentrant": False}, "save_only_model": False}
# Defaults de la entrega (A100 de 40 GB). fp16 y "auto" existen para T4 x2 (Kaggle, desarrollo):
# la T4 no tiene bf16 nativo y "auto" reparte el modelo entre GPU (paralelismo de modelo en un proceso).
PRECISIONES = {"bf16": "bfloat16", "fp16": "float16"}
DISPOSITIVOS = ("unico", "auto")
EJECUCION = {"precision": "bf16", "dispositivos": "unico", "guardar_cada": 50}

def aplicar_lora(peft, modelo, config):
    """LoRA nuevo, o el adapter de `adapter_inicial` entrenable (mismo r y módulos con que se publicó)."""
    inicial = config.get("adapter_inicial")
    if inicial is None:
        return peft.get_peft_model(modelo, peft.LoraConfig(**LORA, revision=config["revision"]))
    origen = {"revision": inicial["revision"], "subfolder": inicial["subcarpeta"]}
    previo = peft.PeftConfig.from_pretrained(inicial["repo"], **origen)
    if (previo.base_model_name_or_path, previo.revision) != (config["modelo"], config["revision"]):
        raise ValueError("adapter_inicial entrenado sobre otra base o revisión")
    return peft.PeftModel.from_pretrained(modelo, inicial["repo"], config=previo, is_trainable=True, **origen)

def cargar_parametros(ruta: Path) -> dict[str, str]:
    """{código: valor con su unidad}, desde `ruta/parametros.yaml`."""
    datos = yaml.safe_load((Path(ruta) / "parametros.yaml").read_text(encoding="utf-8"))
    return {p["codigo"]: valor_como_texto(p["valor"], p["unidad"]) for p in datos["parametros"]}


def linea_de_valores(cuerpo: str, valores: dict[str, str]) -> str:
    """«Valores: P-TDE-3 = 15 min; P-TDE-4 = 60 min.» con los parámetros que cita el cuerpo, en orden de aparición."""
    citados = list(dict.fromkeys(f"{prefijo}-{n}" for prefijo, desde, hasta in PATRON_PARAMETRO.findall(cuerpo)
                                 for n in range(int(desde), int(hasta or desde) + 1)))
    return ("Valores: " + "; ".join(f"{c} = {valores[c]}" for c in citados) + ".") if citados else ""


def cargar_normas(ruta: Path) -> list[Seccion]:
    """Las secciones de `ruta`, en orden alfabético de archivo."""
    valores = cargar_parametros(ruta)
    secciones = []
    for archivo in sorted(Path(ruta).glob("NOR-*.md")):
        cuerpo = archivo.read_text(encoding="utf-8").strip()
        secciones.append(Seccion(archivo.stem, cuerpo, linea_de_valores(cuerpo, valores)))
    return secciones

def escribir_normas(base: Path, destino: Path, valores: dict[str, int]) -> Path:
    """Copia las secciones de `base` a `destino` (nueva) con `valores` aplicados a sus parámetros."""
    base, destino = Path(base), Path(destino)
    entradas = parametros_base(base)
    desconocidos = set(valores) - {p["codigo"] for p in entradas}
    if desconocidos:
        raise ValueError(f"parámetros inexistentes: {sorted(desconocidos)}")
    destino.mkdir(parents=True)
    for archivo in sorted(base.glob("NOR-*.md")):
        shutil.copyfile(archivo, destino / archivo.name)
    for entrada in entradas:
        if entrada["codigo"] in valores:
            valor = valores[entrada["codigo"]]
            if type(valor) is not int or valor < 0:
                raise ValueError("los valores de parámetros son enteros no negativos")
            entrada["valor"] = valor
    (destino / "parametros.yaml").write_text(
        yaml.safe_dump({"parametros": entradas}, allow_unicode=True, sort_keys=False), encoding="utf-8")
    cargar_parametros(destino)  # falla aquí si el archivo escrito no es legible por el kit
    return destino


class CarpetasNormas:
    """Una carpeta por conjunto de valores, creada una sola vez bajo `raiz`, con su buscador.

    `fabrica(ruta)` arma el buscador igual que la entrega (por ejemplo `entrega.construir_buscador`).
    """

    def __init__(self, base: Path, raiz: Path, fabrica):
        self.base, self.raiz, self.fabrica = Path(base), Path(raiz), fabrica
        self.originales = {p["codigo"]: p["valor"] for p in parametros_base(self.base)}
        self._carpetas: dict[tuple, tuple[Path, object]] = {}

    def completar(self, valores: dict[str, int]) -> dict[str, int]:
        """Valores originales con `valores` aplicados encima."""
        return {**self.originales, **valores}

    def obtener(self, valores: dict[str, int]):
        """(ruta, buscador) de la carpeta con esos valores sobre los originales."""
        completos = self.completar(valores)
        clave = tuple(sorted(completos.items()))
        if clave not in self._carpetas:
            ruta = escribir_normas(self.base, self.raiz / f"normas-{len(self._carpetas):05d}", completos)
            self._carpetas[clave] = (ruta, self.fabrica(ruta))
        return self._carpetas[clave]

def armar_comando(preparacion, tokens, salida, ejecucion, online, publicar, checkpoint=None):
    comando = [sys.executable, "-m", "scripts.entrenar", "--preparacion", str(preparacion),
               "--tokens", str(tokens), "--salida", str(salida), "--precision", ejecucion["precision"],
               "--dispositivos", ejecucion["dispositivos"], "--guardar-cada", str(ejecucion["guardar_cada"])]
    if online:
        comando.append("--online")
    if publicar:
        comando.append("--publicar")
    if checkpoint:
        comando += ["--reanudar", str(checkpoint)]
    return comando

modelo = cargar_solo_texto(transformers, config["modelo"], config["revision"],
